(function(W){'use strict';const queue=[];let busy=false;const now=()=>(W.performance&&W.performance.now?W.performance.now():Date.now());const IDLE_MS=1500;let idleTimer=null;function idleLater(){if(idleTimer!==null){clearTimeout(idleTimer);idleTimer=null;}if(typeof setTimeout!=='function')return;idleTimer=setTimeout(()=>{idleTimer=null;if(busy||queue.length)return;try{if(self.SMN.Engrave&&typeof self.SMN.Engrave.trimScratch==='function')self.SMN.Engrave.trimScratch(1);}catch(e){}},IDLE_MS);}const priOf=(m)=>(typeof m.pri==='number'&&isFinite(m.pri)?m.pri:5);function next(){let bi=0;for(let i=1;i<queue.length;i++)if(priOf(queue[i])>priOf(queue[bi]))bi=i;return queue.splice(bi,1)[0];}async function run(){if(busy)return;busy=true;while(queue.length){const m=next();try{const t0=now();const job={D:m.D,W:m.W,H:m.H};if(m.back)job.back=true;else if(m.ui){job.ui=String(m.ui);job.params=m.params||null;}else job.card=typeof m.card==='string'?(self.SMN.Cards&&self.SMN.Cards.byId(m.card))||{id:m.card,kind:'unknown',name:''}:m.card;if(typeof m.world==='string'&&m.world)job.world=m.world;const cv=self.SMN.Engrave.paint(job);if(!cv)throw new Error('no canvas');const t1=now();const blob=await cv.convertToBlob({type:'image/jpeg',quality:m.q||0.9});const t2=now();if(typeof self.SMN.Engrave.trimScratch==='function'&&m.W*m.H>1300000)self.SMN.Engrave.trimScratch();W.postMessage({t:'done',key:m.key,blob,ms:t2-t0,pm:t1-t0,em:t2-t1});}catch(e){W.postMessage({t:'fail',key:m.key,error:String(e&&e.message||e)});}}busy=false;idleLater();}W.onmessage=(ev)=>{const m=ev.data;if(!m||m.t!=='job')return;queue.push(m);run();};})(self);